  where kind = 'course_overview') = $expected_content$[{"itemId":"22b198d9-ebcc-5801-8874-d9dd325124e5","courseId":"40000000-0000-4000-8000-000000000004","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"Leadership and Governance","body":"Leadership theories and styles, organisational ethics, governance frameworks, and stakeholder management across the public and private sectors.","topics":[{"chapter":"1-3","description":"Leadership Theories and Models"},{"chapter":"4-5","description":"Leadership Styles and Effectiveness"},{"chapter":"6-7","description":"Ethics and Governance Frameworks"},{"chapter":"8-9","description":"Stakeholder Management and Engagement"},{"chapter":"10","description":"Public Sector Reform and Innovation"}],"examFocus":["Leadership theory definitions and applications","Leadership styles and situational leadership","Ethical leadership principles","Governance structures and responsibilities","Stakeholder analysis and management","Essays on organizational leadership"]}}]$expected_content$::jsonb,
