  where kind = 'course_overview') = $expected_content$[{"itemId":"bba5d149-4d82-5584-a1e9-c89fc82e7c84","courseId":"40000000-0000-4000-8000-000000000009","kind":"course_overview","questionId":null,"sourceKey":"course-overview","parentItemId":null,"revision":1,"payload":{"title":"Nigerian Peoples and Culture","body":"A General Studies course surveying Nigerian peoples and culture. It covers the concept, characteristics and components of culture; an ethno-historical survey of Nigeria's major groups and geopolitical zones; the roles of Christianity and Islam in political culture; gender and culture; the Nigerian Civil War; and the political economy from agriculture to oil. A 100-level course required of all UNILAG students; Direct Entry students take it in 200 Level.","topics":[{"chapter":"1","description":"Culture and Society"},{"chapter":"2","description":"Nigeria: Ethno-Historical Survey"},{"chapter":"3","description":"Historical Foundation of Nigerian Culture"},{"chapter":"4","description":"Christianity and Political Culture"},{"chapter":"5","description":"Islam and Political Culture"},{"chapter":"6","description":"Nigerian Cultural Heritage: Marriage and Naming"},{"chapter":"7","description":"Gender and Culture"},{"chapter":"8","description":"Political Economy and Intergroup Relations"}],"examFocus":["Concept, characteristics and components of culture","Geopolitical zones and major ethnic groups of Nigeria","Introduction of Christianity and the role of Badagry","Spread of Islam in Kanem-Borno and Hausaland","Pre-colonial women and the Aba Women's Riot of 1929","The Nigerian Civil War: causes, key figures and outcomes","Political economy: agriculture, oil at Oloibiri, and national development","The 1914 amalgamation and intergroup relations"]}}]$expected_content$::jsonb,
