  where kind = 'cbt_question') = $expected_content$[{"itemId":"ea8782ee-25da-559f-9373-9cfea75a87d9","courseId":"40000000-0000-4000-8000-000000000009","kind":"cbt_question","questionId":"84967dcc-3128-41ce-8604-8320286659f3","sourceKey":"quiz:1","parentItemId":null,"revision":1,"payload":{"prompt":"Culture is best defined as:","options":["A set of government laws","The totality of a people's way of life","An individual's personal habits","A particular religious practice"],"correctOption":1,"section":"Culture and Society"}},{"itemId":"041c6b8f-b069-5965-bb03-ce5c1001388e","courseId":"40000000-0000-4000-8000-000000000009","kind":"cbt_question","questionId":"0101c372-08f4-484d-926b-b44f00d28f7b","sourceKey":"quiz:10","parentItemId":null,"revision":1,"payload":{"prompt":"Nigeria is estimated to have approximately how many ethnic groups?","options":["About 50","About 150","About 350 to 400","About 1,000"],"correctOption":2,"section":"Ethno-Historical Survey"}},{"itemId":"49aae16a-eea3-513a-b70f-3fbcf252efe7","courseId":"40000000-0000-4000-8000-000000000009","kind":"cbt_question","questionId":"adf6007f-ff28-4f51-b396-8ecd0eac3353","sourceKey":"quiz:100","parentItemId":null,"revision":1,"payload":{"prompt":"When was Kaduna founded by the British?","options":["1912","1909","1910","1913"],"correctOption":3,"section":"Practice Examination"}},{"itemId":"1d1f8f00-16cf-550b-b41d-b3a5eb5b2da9","courseId":"40000000-0000-4000-8000-000000000009","kind":"cbt_question","questionId":"5cc47c42-4f1c-499a-be9b-29c25421753e","sourceKey":"quiz:101","parentItemId":null,"revision":1,"payload":{"prompt":"Traditional Nigerian cultures enjoined every member not to _______","options":["Shun corrupt acts","Be untrustworthy","Respect the rules of social conducts and engagements","Pursue integrity"],"correctOption":1,"section":"Practice Examination"}},{"itemId":"be844f22-4f15-56d1-9aa6-335314fa45cc","courseId":"40000000-0000-4000-8000-000000000009","kind":"cbt_question","questionId":"23132a9c-79d1-4