  where kind = 'cbt_question') = $expected_content$[{"itemId":"cba25b3c-f8ec-5df1-b865-2f79b781e406","courseId":"40000000-0000-4000-8000-000000000013","kind":"cbt_question","questionId":"5c96c0ac-63a9-4ded-9988-bc73cba10e9f","sourceKey":"quiz:1","parentItemId":null,"revision":1,"payload":{"prompt":"“Cogito ergo sum” is ascribed to","options":["Aristotle","Thales","Spinoza","Descartes"],"correctOption":3,"section":"Master Question Bank"}},{"itemId":"04f5234c-104d-5c09-a061-16148071999b","courseId":"40000000-0000-4000-8000-000000000013","kind":"cbt_question","questionId":"39855792-af43-4adb-b747-93afdfd35e34","sourceKey":"quiz:10","parentItemId":null,"revision":1,"payload":{"prompt":"According to _____, to be is to be perceived","options":["Plato","Hegel","Berkeley","Aristotle"],"correctOption":2,"section":"Master Question Bank"}},{"itemId":"f0a93073-d2a7-574f-a414-bf5bd0e0f5c4","courseId":"40000000-0000-4000-8000-000000000013","kind":"cbt_question","questionId":"1ee02a21-3372-49fa-a324-eea032927e57","sourceKey":"quiz:100","parentItemId":null,"revision":1,"payload":{"prompt":"One important feature of scientific findings is their ability to remain","options":["measurable through complex formulas","repeatable under similar conditions","observable during technical experiments","predictable within laboratory systems"],"correctOption":1,"section":"Master Question Bank"}},{"itemId":"dc674693-053f-5117-a8cb-e29530287572","courseId":"40000000-0000-4000-8000-000000000013","kind":"cbt_question","questionId":"c4126f2c-31bd-47cf-ab58-61d4e0e57484","sourceKey":"quiz:101","parentItemId":null,"revision":1,"payload":{"prompt":"Aristotle believed music and art influence human character and social","options":["order and behaviour","commerce and trade","science and invention","wealth and ambition"],"correctOption":0,"section":"Master Question Bank"}},{"itemId":"f62d60ad-a549-51b4-962b-4cdd6105e10b","courseId":"40000000-0000-4000-8000-000000000013","kind":"cbt_question","questionId":"bc2