  where kind = 'cbt_question') = $expected_content$[{"itemId":"87d1dc3a-b164-5da5-bde2-bb72e67d58b2","courseId":"40000000-0000-4000-8000-000000000015","kind":"cbt_question","questionId":"add4fd37-0b3f-4fad-b448-33989fe366ea","sourceKey":"quiz:1","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the stated reasons green management is important to organizations?","options":["Environmental Sustainability — reduces pollution, waste, and resource depletion, preserving ecosystems and biodiversity","Government regulations","Global sustainability frameworks","Regulatory compliance"],"correctOption":0,"section":"Topic 1 — Introduction to Green Management"}},{"itemId":"96952689-e7cf-537d-ae9e-4b9188ed931e","courseId":"40000000-0000-4000-8000-000000000015","kind":"cbt_question","questionId":"7f62e3a3-fd38-43d5-8b63-3657ebc47542","sourceKey":"quiz:10","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the stated benefits of green management to society?","options":["Competitive advantage","Employee satisfaction and retention","Climate change mitigation","It improves resource efficiency and lowers operating cost"],"correctOption":2,"section":"Topic 1 — Introduction to Green Management"}},{"itemId":"4220de51-18fd-5369-95e8-d304d04aa7dc","courseId":"40000000-0000-4000-8000-000000000015","kind":"cbt_question","questionId":"51d4e574-3b23-4cd7-8f3a-d4a85c916d02","sourceKey":"quiz:100","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is NOT one of the stated challenges of implementing the circular economy?","options":["Inconsistent environmental regulations (bylaws)","Complex product designs that are difficult to repair or redesign","Meets environmental regulation and sustainability goals","Limited recycling infrastructure in some sub-regions"],"correctOption":2,"section":"Topic 2 — Environmental Principles and Concepts"}},{"itemId":"0be3ca73-1a46-5902-8245-549d18f821ec","courseId":"40000000-0000-4000-8000-000000000015","kind":"cbt_question","questionId":"2d5096f2-fdfb-46be-8671-f08373c5405f","sourceKey":"quiz:101","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the stated importance of integrating sustainability into business strategy?","options":["It enhances long-term business growth","Producing electric and hybrid vehicles","Process innovation","It lowers production and operation cost"],"correctOption":0,"section":"Topic 3 — Strategic Green Management"}},{"itemId":"7090808f-00b9-58f2-9d3e-77c1c1795c53","courseId":"40000000-0000-4000-8000-000000000015","kind":"cbt_question","questionId":"eb80952b-cb17-44d3-9a8e-6bc23312b1d8","sourceKey":"quiz:102","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the stated key elements of a sustainable business strategy?","options":["It enhances brand image and customer trust","It reduces environmental impact","Leadership commitment","It reduces material use"],"correctOption":2,"section":"Topic 3 — Strategic Green Management"}},{"itemId":"52e3aac7-1c11-5a29-ac74-984b18a641c8","courseId":"40000000-0000-4000-8000-000000000015","kind":"cbt_question","questionId":"472a6399-67a7-4946-85de-599c1e205b40","sourceKey":"quiz:103","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the stated steps for integrating sustainability into business strategy?","options":["It improves corporate reputation","Assess current environmental and social impact","High initial investment cost","Producing electric and hybrid vehicles"],"correctOption":1,"section":"Topic 3 — Strategic Green Management"}},{"itemId":"59fb57c2-a930-5a4f-b80c-35b9913a078e","courseId":"40000000-0000-4000-8000-000000000015","kind":"cbt_question","questionId":"4f30b1d0-197c-424f-90bf-39026c521bf6","sourceKey":"quiz:104","parentItemId":null,"revision":1,"payload":{"prompt":"Which of the following is one of the stated objectives of green innovation?","opti